#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cstdint>
#include <cuda.h>
#include <cuda_runtime.h>

namespace {

constexpr int TILE = 32;
constexpr int SMEM_PITCH = TILE + 4;
__device__ __forceinline__ void upper_tri_load_tile(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float (*As)[SMEM_PITCH],
    float (*Bs)[SMEM_PITCH],
    int N,
    int tile_row,
    int tile_col,
    int k_tile,
    int warp_id,
    int lane
) {
    const int k_base = k_tile * TILE;
    const int tid = warp_id * 32 + lane;
    constexpr int WARPS_PER_BLOCK = 4;

    for (int chunk = tid * 8; chunk < TILE * TILE; chunk += WARPS_PER_BLOCK * 32 * 8) {
        const int local_row = chunk / TILE;
        const int local_col = chunk - local_row * TILE;
        const int a_row = tile_row * TILE + local_row;
        const int a_col = k_base + local_col;
        const int b_row = k_base + local_row;
        const int b_col = tile_col * TILE + local_col;

        const bool a_vec_ok =
            a_row < N && a_col + 7 < N && a_col >= a_row &&
            (reinterpret_cast<uintptr_t>(A + a_row * N + a_col) & 15u) == 0;
        const bool b_vec_ok =
            b_row < N && b_col + 7 < N && b_col >= b_row &&
            (reinterpret_cast<uintptr_t>(B + b_row * N + b_col) & 15u) == 0;

#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
        if (a_vec_ok) {
            const unsigned smem = __cvta_generic_to_shared(&As[local_row][local_col]);
            asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                         :: "r"(smem), "l"(A + a_row * N + a_col));
            const unsigned smem2 = __cvta_generic_to_shared(&As[local_row][local_col + 4]);
            asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                         :: "r"(smem2), "l"(A + a_row * N + a_col + 4));
        } else {
            #pragma unroll
            for (int q = 0; q < 8; ++q) {
                const int col = local_col + q;
                const int global_col = k_base + col;
                As[local_row][col] =
                    (a_row < N && global_col < N && global_col >= a_row)
                        ? A[a_row * N + global_col]
                        : 0.0f;
            }
        }

        if (b_vec_ok) {
            const unsigned smem = __cvta_generic_to_shared(&Bs[local_row][local_col]);
            asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                         :: "r"(smem), "l"(B + b_row * N + b_col));
            const unsigned smem2 = __cvta_generic_to_shared(&Bs[local_row][local_col + 4]);
            asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                         :: "r"(smem2), "l"(B + b_row * N + b_col + 4));
        } else {
            #pragma unroll
            for (int q = 0; q < 8; ++q) {
                const int col = local_col + q;
                const int global_row = k_base + local_row;
                const int global_col = tile_col * TILE + col;
                Bs[local_row][col] =
                    (global_row < N && global_col < N && global_col >= global_row)
                        ? B[global_row * N + global_col]
                        : 0.0f;
            }
        }
#else
        if (a_vec_ok) {
            const float4 av0 = *reinterpret_cast<const float4*>(A + a_row * N + a_col);
            const float4 av1 = *reinterpret_cast<const float4*>(A + a_row * N + a_col + 4);
            As[local_row][local_col + 0] = av0.x;
            As[local_row][local_col + 1] = av0.y;
            As[local_row][local_col + 2] = av0.z;
            As[local_row][local_col + 3] = av0.w;
            As[local_row][local_col + 4] = av1.x;
            As[local_row][local_col + 5] = av1.y;
            As[local_row][local_col + 6] = av1.z;
            As[local_row][local_col + 7] = av1.w;
        } else {
            #pragma unroll
            for (int q = 0; q < 8; ++q) {
                const int col = local_col + q;
                const int global_col = k_base + col;
                As[local_row][col] =
                    (a_row < N && global_col < N && global_col >= a_row)
                        ? A[a_row * N + global_col]
                        : 0.0f;
            }
        }

        if (b_vec_ok) {
            const float4 bv0 = *reinterpret_cast<const float4*>(B + b_row * N + b_col);
            const float4 bv1 = *reinterpret_cast<const float4*>(B + b_row * N + b_col + 4);
            Bs[local_row][local_col + 0] = bv0.x;
            Bs[local_row][local_col + 1] = bv0.y;
            Bs[local_row][local_col + 2] = bv0.z;
            Bs[local_row][local_col + 3] = bv0.w;
            Bs[local_row][local_col + 4] = bv1.x;
            Bs[local_row][local_col + 5] = bv1.y;
            Bs[local_row][local_col + 6] = bv1.z;
            Bs[local_row][local_col + 7] = bv1.w;
        } else {
            #pragma unroll
            for (int q = 0; q < 8; ++q) {
                const int col = local_col + q;
                const int global_row = k_base + local_row;
