__global__ void upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    const int num_tiles = (N + TILE - 1) / TILE;
    int tile_row = 0;
    int upper_tile_id = static_cast<int>(blockIdx.x);
    while (tile_row < num_tiles && upper_tile_id >= num_tiles - tile_row) {
        upper_tile_id -= num_tiles - tile_row;
        ++tile_row;
    }
    const int tile_col = tile_row + upper_tile_id;
    constexpr int WARPS_PER_BLOCK = 4;
    const int warp_id = threadIdx.y;
    const int lane = threadIdx.x;
    __shared__ __align__(16) float As[2][TILE][SMEM_PITCH];
    __shared__ __align__(16) float Bs[2][TILE][SMEM_PITCH];

    float acc[2][4] = {};
    const int warp_row = (warp_id >> 1) * 16;
    const int warp_col = (warp_id & 1) * 16;
    const int row_base = tile_row * TILE + warp_row + (lane >> 2) * 2;
    const int col_base = tile_col * TILE + warp_col + (lane & 3) * 4;
    const int first_k_tile = tile_row;
    const int last_k_tile = tile_col;
    int stage = 0;

    upper_tri_load_tile(A, B, As[stage], Bs[stage], N, tile_row, tile_col, first_k_tile, warp_id, lane);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;");
    asm volatile("cp.async.wait_group 0;");
#endif
    __syncthreads();

    for (int k_tile = first_k_tile; k_tile <= last_k_tile; ++k_tile) {
        const bool has_next = k_tile < last_k_tile;
        const int next_stage = stage ^ 1;

        if (has_next) {
            upper_tri_load_tile(A, B, As[next_stage], Bs[next_stage], N,
                                tile_row, tile_col, k_tile + 1, warp_id, lane);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
            asm volatile("cp.async.commit_group;");
#endif
        }

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a[2];
            float b[4];
            #pragma unroll
            for (int i = 0; i < 2; ++i) {
                a[i] = As[stage][warp_row + (lane >> 2) * 2 + i][k];
            }
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                b[j] = Bs[stage][k][warp_col + (lane & 3) * 4 + j];
            }
            #pragma unroll
            for (int i = 0; i < 2; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
                }
            }
        }

        if (has_next) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
            asm volatile("cp.async.wait_group 0;");
#endif
            __syncthreads();
            stage = next_stage;
        }
    }

    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        const int row = row_base + i;
        const int col = col_base;
        const bool vec_store_ok =
            row < N && col + 3 < N && row <= col &&
            (reinterpret_cast<uintptr_t>(C + row * N + col) & 15u) == 0;
        if (vec_store_ok) {
            float4 out;
            out.x = acc[i][0];
            out.y = acc[i][1];
            out.z = acc[i][2];
            out.w = acc[i][3];
            *reinterpret_cast<float4*>(C + row * N + col) = out;
        } else {
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                const int scalar_col = col + j;
                if (row < N && scalar_col < N && row <= scalar_col) {
                    C[row * N + scalar_col] = acc[i][j];
                }
            }
        }
    }
}

} // namespace

torch::Tensor upper_tri_mm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.sizes() == B.sizes(), "A and B must have identical shapes");
    TORCH_CHECK(
        A.device() == B.device(),
        "A and B must be on the same CUDA device"
    );
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int N = static_cast<int>(A.size(0));
    at::cuda::CUDAGuard device_guard(A.device());

    auto C = torch::zeros({N, N}, A.options());

    if (N == 0) {
        return C;
    }

    const dim3 block(32, 4);
    const dim3 grid((N + TILE - 1) / TILE * ((N + TILE - 1) / TILE + 1) / 2, 1);

    upper_triangular_matmul_kernel<<<
        grid,
        block,
        0,
        at::cuda::getCurrentCUDAStream(A.device().index())
    >>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
